import{GARDEN_CONFIG as c}from"./config.min.js";import{seasonAt as m,wrapHour as g,clamp01 as u,SPRING as x}from"./clock.min.js";export const STATES=["sunny","cloudy","windy","stormy"];export function weightsFor(t,n=c){return n.weather.weights[t]||n.weather.weights.summer}export function nextState(t,n,e,o=c){const s=weightsFor(n,o);let r=0;for(const a of STATES)a!==t&&(r+=s[a]||0);if(r<=0)return t;let i=0;const l=u(e)*r;for(const a of STATES)if(a!==t&&(i+=s[a]||0,l<=i))return a;return STATES[STATES.length-1]===t?STATES[0]:STATES[STATES.length-1]}export function dwellFor(t,n=c){const e=n.weather.dwell;return e.min+u(t)*(e.max-e.min)}export function temperatureAt(t,n=c){const e=n.weather.temperature,o=(Math.sin((g(t)-6)*Math.PI/12)+1)/2;return e.coldest+(e.warmest-e.coldest)*o}export function precipFor(t,n,e=c){if(t<=.01)return"none";const o=e.weather.temperature,s=temperatureAt(n,e);return s<o.snowBelow?"snow":s<o.sleetBelow?"sleet":"rain"}export function gustAt(t,n=c){const e=n.weather.gust;let o=0;for(let r=0;r<e.periods.length;r++)o+=e.weights[r]*Math.sin(t*Math.PI*2/e.periods[r]+r*1.7+r*r*.7);const s=Math.pow(u((o+1)/2),e.shape);return e.floor+(e.peak-e.floor)*s}export function blendStates(t,n,e,o=c){const s=o.weather.states[t],r=o.weather.states[n],i=l=>s[l]+(r[l]-s[l])*u(e);return{gloom:i("gloom"),wind:i("wind"),rain:i("rain")}}export function createWeather(t="sunny"){return{state:t,from:t,transition:1,held:0,dwell:30,season:null,angle:.8,gloom:0,windStrength:0,gust:1,rain:0,wind:{x:0,z:0},precip:"none"}}export function stepWeather(t,n,e,o=0,s=Math.random,r=!1,i=c){const l=i.weather,a=r?l.reducedTransitionSeconds:l.transitionSeconds,h=m(e);if(h!==t.season){const f=t.season===null;t.season=h,!f&&h===x&&(t.from=t.state,t.state="sunny",t.transition=0,t.held=0,t.dwell=l.springClearHours*(i.clock.cycleSeconds/24))}t.transition<1?t.transition=Math.min(1,t.transition+n/a):(t.held+=n,t.held>=t.dwell&&(t.from=t.state,t.state=nextState(t.state,h,s(),i),t.dwell=dwellFor(s(),i),t.held=0,t.transition=0));const d=blendStates(t.from,t.state,t.transition,i);t.gloom=d.gloom,t.rain=d.rain;const p=gustAt(o,i);return t.gust=r?1+(p-1)*l.gust.reducedDamp:p,t.windStrength=d.wind*t.gust,t.angle+=l.turnRate*n*(r?.4:1),t.wind.x=Math.cos(t.angle)*t.windStrength,t.wind.z=Math.sin(t.angle)*t.windStrength,t.precip=precipFor(t.rain,e,i),t}export function overcastAt(t,n=null,e=c){const o=e.weather;let s=u(t);if(n){const r=Math.max(n.rain||0,n.snow||0);r>=o.precipitation.visibleRate&&(s=Math.max(s,u(r)*o.fallingOvercast))}return s}export function weatherWords(t,n=null,e=c){const o=e.weather,s=o.precipitation.visibleRate,r=n&&n.rain>=s,i=n&&n.snow>=s,l=(t.windStrength||0)>=o.windyAbove;let a="";return r&&i?a="sleet":i?a="snow":r&&(a="rain"),a?l?`windy ${a}`:a:l?"windy":t.gloom>o.cloudyAbove?"cloudy":"clear"}
